changes.content:
plugins {
    id 'com.android.application'
}

// One switch owns the entire runtime diagnostic system.
// Use exactly "on" while developing and flip to "off" for production builds.
def cabrushDevModeRaw = providers.gradleProperty('cabrush.devMode').orElse('on').get().toString().toLowerCase()
if (!(cabrushDevModeRaw in ['on', 'off'])) {
    throw new GradleException("cabrush.devMode must be 'on' or 'off', got: " + cabrushDevModeRaw)
}
def cabrushDevMode = cabrushDevModeRaw == 'on'

android {
    namespace 'com.fallpoint.pocketsculpt'
    compileSdk 35

    defaultConfig {
        applicationId 'com.fallpoint.pocketsculpt'
        minSdk 24
        targetSdk 35
        versionCode 10
        versionName '0.4.1'
        buildConfigField 'boolean', 'ENGINE_DIAGNOSTICS', cabrushDevMode ? 'true' : 'false'
    }

    buildFeatures {
        buildConfig true
    }

    buildTypes {
        release {
            minifyEnabled false
            proguardFiles getDefaultProguardFile('proguard-android-optimize.txt'), 'proguard-rules.pro'
        }
    }

    compileOptions {
        sourceCompatibility JavaVersion.VERSION_17
        targetCompatibility JavaVersion.VERSION_17
    }
}

// AVS 0.1.1 Surface Truth VSS compiles the exact dependency-free volume +
// surface conversion code used by Android. preBuild is blocked until field
// truth, winding, seams, deterministic extraction, cache rebuild equivalence,
// snapshots, stress and Android-equivalent culling screenshots all pass.
def vssClassesDir = layout.buildDirectory.dir('vss/classes')
def vssReportDir = layout.buildDirectory.dir('vss/report')

tasks.register('vssCompile', JavaCompile) {
    source = files(
            'src/main/java/com/fallpoint/pocketsculpt/BrushMode.java',
            'src/main/java/com/fallpoint/pocketsculpt/EngineDiagnostics.java',
            'src/main/java/com/fallpoint/pocketsculpt/PrimitiveLongIntMap.java',
            'src/main/java/com/fallpoint/pocketsculpt/AvsVolume.java',
            'src/main/java/com/fallpoint/pocketsculpt/AvsSnapshot.java',
            'src/main/java/com/fallpoint/pocketsculpt/AvsSurfaceCache.java',
            'src/main/java/com/fallpoint/pocketsculpt/SculptMesh.java',
            '../tools/VssVerify.java'
    )
    classpath = files()
    destinationDirectory.set(vssClassesDir)
    options.encoding = 'UTF-8'
    sourceCompatibility = '17'
    targetCompatibility = '17'
}

tasks.register('vssVerify', JavaExec) {
    dependsOn 'vssCompile'
    classpath = files(vssClassesDir)
    mainClass.set('com.fallpoint.pocketsculpt.VssVerify')
    args(vssReportDir.get().asFile.absolutePath)
    jvmArgs '-Djava.awt.headless=true', '-Xmx1200m'
}

tasks.named('preBuild').configure {
    dependsOn 'vssVerify'
}

package com.fallpoint.pocketsculpt;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Engine-wide diagnostic bus.
 *
 * This class intentionally has no Android dependencies so the same AVS core can
 * still be compiled by VSS. Runtime diagnostics are opt-in and become near-zero
 * cost when disabled: every entry point returns before allocating event text.
 *
 * The Android shell installs a DumpListener only when BuildConfig says the
 * developer diagnostic system is enabled.
 */
final class EngineDiagnostics {
    static final int SCHEMA_VERSION = 1;
    static final int EVENT_CAPACITY = 65_536;
    private static final long ANOMALY_DUMP_COOLDOWN_MS = 15_000L;

    interface DumpListener {
        void requestDump(String reason);
    }

    static final class Event {
        final long sequence;
        final long elapsedNanos;
        final long threadId;
        final String threadName;
        final String category;
        final String name;
        final String detail;

        Event(long sequence, long elapsedNanos, long threadId, String threadName,
              String category, String name, String detail) {
            this.sequence = sequence;
            this.elapsedNanos = elapsedNanos;
            this.threadId = threadId;
            this.threadName = threadName;
            this.category = category;
            this.name = name;
            this.detail = detail;
        }
    }

    static final class Snapshot {
        final long capturedWallMillis;
        final long sessionElapsedNanos;
        final long droppedEvents;
        final List<Event> events;
        final Map<String, Long> counters;
        final Map<String, Double> gauges;
        final Map<String, String> state;

        Snapshot(long capturedWallMillis, long sessionElapsedNanos, long droppedEvents,
                 List<Event> events, Map<String, Long> counters,
                 Map<String, Double> gauges, Map<String, String> state) {
            this.capturedWallMillis = capturedWallMillis;
            this.sessionElapsedNanos = sessionElapsedNanos;
            this.droppedEvents = droppedEvents;
            this.events = events;
            this.counters = counters;
            this.gauges = gauges;
            this.state = state;
        }
    }

    private static final Object LOCK = new Object();
    private static final Event[] RING = new Event[EVENT_CAPACITY];
    private static final LinkedHashMap<String, Long> COUNTERS = new LinkedHashMap<>();
    private static final LinkedHashMap<String, Double> GAUGES = new LinkedHashMap<>();
    private static final LinkedHashMap<String, String> STATE = new LinkedHashMap<>();
    private static final LinkedHashMap<String, Long> LAST_ANOMALY_DUMP = new LinkedHashMap<>();

    private static volatile boolean enabled;
    private static volatile DumpListener dumpListener;
    private static long sessionStartNanos = System.nanoTime();
    private static long nextSequence;
    private static long droppedEvents;

    private EngineDiagnostics() {}

    static void configure(boolean value) {
        if (value) {
            synchronized (LOCK) {
                if (!enabled) {
                    sessionStartNanos = System.nanoTime();
                    nextSequence = 0L;
                    droppedEvents = 0L;
                    COUNTERS.clear();
                    GAUGES.clear();
                    STATE.clear();
                    LAST_ANOMALY_DUMP.clear();
                    for (int i = 0; i < RING.length; i++) RING[i] = null;
                }
                enabled = true;
            }
            record("diagnostics", "enabled", "schema=" + SCHEMA_VERSION
                    + " capacity=" + EVENT_CAPACITY);
        } else {
            enabled = false;
            dumpListener = null;
        }
    }

    static boolean isEnabled() {
        return enabled;
    }

    static void setDumpListener(DumpListener listener) {
        if (!enabled) return;
        dumpListener = listener;
    }

    static void record(String category, String name, String detail) {
        if (!enabled) return;
        Thread thread = Thread.currentThread();
        long elapsed = System.nanoTime() - sessionStartNanos;
        synchronized (LOCK) {
            long seq = nextSequence++;
            int slot = (int) (seq % EVENT_CAPACITY);
            if (RING[slot] != null && seq >= EVENT_CAPACITY) droppedEvents++;
            RING[slot] = new Event(
                    seq,
                    elapsed,
                    thread.getId(),
                    thread.getName(),
                    safe(category),
                    safe(name),
                    detail == null ? "" : detail
            );
        }
    }

    static void counter(String name, long delta) {
        if (!enabled) return;
        synchronized (LOCK) {
            Long old = COUNTERS.get(name);
            COUNTERS.put(name, (old == null ? 0L : old) + delta);
        }
    }

    static void gauge(String name, double value) {
        if (!enabled || !Double.isFinite(value)) return;
        synchronized (LOCK) {
            GAUGES.put(name, value);
        }
    }

    static void state(String name, String value) {
        if (!enabled) return;
        synchronized (LOCK) {
            STATE.put(name, value == null ? "" : value);
        }
    }

    static void anomaly(String code, String detail) {
        if (!enabled) return;
        record("anomaly", code, detail);
        counter("anomaly." + safe(code), 1L);

        DumpListener listener = dumpListener;
        if (listener == null) return;

        long now = System.currentTimeMillis();
        boolean request = false;
        synchronized (LOCK) {
            Long last = LAST_ANOMALY_DUMP.get(code);
            if (last == null || now - last >= ANOMALY_DUMP_COOLDOWN_MS) {
                LAST_ANOMALY_DUMP.put(code, now);
                request = true;
            }
        }
        if (request) {
            try {
                listener.requestDump("anomaly-" + safe(code));
            } catch (Throwable ignored) {
                // Diagnostics must never be able to crash the sculpt engine.
            }
        }
    }

    static Snapshot snapshot() {
        synchronized (LOCK) {
            long end = nextSequence;
            long start = Math.max(0L, end - EVENT_CAPACITY);
            ArrayList<Event> events = new ArrayList<>((int) Math.min(end, EVENT_CAPACITY));
            for (long seq = start; seq < end; seq++) {
                Event e = RING[(int) (seq % EVENT_CAPACITY)];
                if (e != null && e.sequence == seq) events.add(e);
            }
            return new Snapshot(
                    System.currentTimeMillis(),
                    System.nanoTime() - sessionStartNanos,
                    droppedEvents,
                    events,
                    new LinkedHashMap<>(COUNTERS),
                    new LinkedHashMap<>(GAUGES),
                    new LinkedHashMap<>(STATE)
            );
        }
    }

    static long nowNanos() {
        return enabled ? System.nanoTime() : 0L;
    }

    static void timed(String category, String name, long startNanos, String detail) {
        if (!enabled || startNanos == 0L) return;
        long duration = System.nanoTime() - startNanos;
        gauge(category + "." + name + ".last_ms", duration / 1_000_000.0);
        record(category, name, (detail == null || detail.isEmpty() ? "" : detail + " ")
                + "duration_ns=" + duration);
    }

    private static String safe(String s) {
        if (s == null || s.isEmpty()) return "unknown";
        return s;
    }
}

package com.fallpoint.pocketsculpt;

import android.app.ActivityManager;
import android.content.Context;
import android.os.Build;
import android.os.Debug;
import android.os.PowerManager;
import android.os.SystemClock;
import android.util.DisplayMetrics;

import java.io.BufferedWriter;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.io.PrintWriter;
import java.io.StringWriter;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.Arrays;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Android owner for PocketSculpt's deep engine diagnostics.
 *
 * The single Gradle switch cabrush.devMode=on/off controls whether this is
 * installed. With it off no writer thread, crash hook, event listener or
 * diagnostic I/O is created.
 */
final class AndroidDiagnostics {
    private final Context context;
    private final ExecutorService writer;
    private final AtomicBoolean dumpPending = new AtomicBoolean();
    private final Thread.UncaughtExceptionHandler previousHandler;
    private volatile String lastDumpPath = "";

    private AndroidDiagnostics(Context context) {
        this.context = context.getApplicationContext();
        this.writer = Executors.newSingleThreadExecutor(r -> {
            Thread t = new Thread(r, "PocketSculpt-DiagnosticWriter");
            t.setDaemon(true);
            return t;
        });
        this.previousHandler = Thread.getDefaultUncaughtExceptionHandler();

        EngineDiagnostics.setDumpListener(this::requestDump);
        Thread.setDefaultUncaughtExceptionHandler((thread, throwable) -> {
            try {
                EngineDiagnostics.record(
                        "crash",
                        "uncaught_exception",
                        "thread=" + thread.getName()
                                + " type=" + throwable.getClass().getName()
                                + " message=" + String.valueOf(throwable.getMessage())
                );
                writeDump("uncaught-" + throwable.getClass().getSimpleName(), throwable);
            } catch (Throwable ignored) {
            }
            if (previousHandler != null) {
                previousHandler.uncaughtException(thread, throwable);
            }
        });

        seedDeviceState();
        EngineDiagnostics.record("android", "diagnostics_installed",
                "pid=" + android.os.Process.myPid());
    }

    static AndroidDiagnostics install(Context context) {
        EngineDiagnostics.configure(BuildConfig.ENGINE_DIAGNOSTICS);
        if (!BuildConfig.ENGINE_DIAGNOSTICS) return null;
        return new AndroidDiagnostics(context);
    }

    void requestManualDump(String reason) {
        if (!BuildConfig.ENGINE_DIAGNOSTICS) return;
        EngineDiagnostics.record("diagnostics", "manual_dump_requested", "reason=" + reason);
        requestDump("manual-" + reason);
    }

    String lastDumpPath() {
        return lastDumpPath;
    }

    void onLifecycle(String state) {
        if (!BuildConfig.ENGINE_DIAGNOSTICS) return;
        EngineDiagnostics.record("android", "lifecycle", state);
        sampleRuntimeState();
    }

    void shutdown() {
        if (!BuildConfig.ENGINE_DIAGNOSTICS) return;
        EngineDiagnostics.record("android", "diagnostics_shutdown", "");
        EngineDiagnostics.setDumpListener(null);
        Thread.setDefaultUncaughtExceptionHandler(previousHandler);
        writer.shutdown();
    }

    private void requestDump(String reason) {
        if (!BuildConfig.ENGINE_DIAGNOSTICS) return;
        if (!dumpPending.compareAndSet(false, true)) {
            EngineDiagnostics.counter("diagnostics.dump_coalesced", 1L);
            return;
        }
        writer.execute(() -> {
            try {
                writeDump(reason, null);
            } catch (Throwable t) {
                EngineDiagnostics.record("diagnostics", "dump_failed",
                        t.getClass().getSimpleName() + ": " + String.valueOf(t.getMessage()));
            } finally {
                dumpPending.set(false);
            }
        });
    }

    private synchronized void writeDump(String reason, Throwable crash) throws IOException {
        sampleRuntimeState();
        EngineDiagnostics.Snapshot snapshot = EngineDiagnostics.snapshot();

        File root = context.getExternalFilesDir(null);
        if (root == null) root = context.getFilesDir();
        File diagnosticsRoot = new File(root, "diagnostics");
        if (!diagnosticsRoot.exists() && !diagnosticsRoot.mkdirs()) {
            throw new IOException("cannot create " + diagnosticsRoot);
        }

        String stamp = fileStamp(System.currentTimeMillis());
        File dir = new File(diagnosticsRoot, "PocketSculpt-" + stamp + "-" + sanitize(reason));
        if (!dir.mkdirs()) throw new IOException("cannot create " + dir);

        writeManifest(new File(dir, "dump.json"), snapshot, reason, crash);
        writeEvents(new File(dir, "events.jsonl"), snapshot);
        writeThreads(new File(dir, "threads.txt"));
        writeSystem(new File(dir, "system.txt"), snapshot, reason);
        if (crash != null) writeCrash(new File(dir, "crash.txt"), crash);

        lastDumpPath = dir.getAbsolutePath();
        try (FileWriter latest = new FileWriter(new File(diagnosticsRoot, "latest.txt"))) {
            latest.write(lastDumpPath);
            latest.write('\n');
        }

        EngineDiagnostics.counter("diagnostics.dumps_written", 1L);
        EngineDiagnostics.state("diagnostics.last_dump", lastDumpPath);
        EngineDiagnostics.record("diagnostics", "dump_complete",
                "reason=" + reason + " path=" + lastDumpPath
                        + " events=" + snapshot.events.size());
    }

    private void seedDeviceState() {
        DisplayMetrics dm = context.getResources().getDisplayMetrics();
        EngineDiagnostics.state("build.version_name", BuildConfig.VERSION_NAME);
        EngineDiagnostics.state("build.version_code", String.valueOf(BuildConfig.VERSION_CODE));
        EngineDiagnostics.state("build.dev_mode", String.valueOf(BuildConfig.ENGINE_DIAGNOSTICS));
        EngineDiagnostics.state("device.manufacturer", Build.MANUFACTURER);
        EngineDiagnostics.state("device.model", Build.MODEL);
        EngineDiagnostics.state("device.device", Build.DEVICE);
        EngineDiagnostics.state("device.sdk", String.valueOf(Build.VERSION.SDK_INT));
        EngineDiagnostics.state("device.release", Build.VERSION.RELEASE);
        EngineDiagnostics.state("device.abis", Arrays.toString(Build.SUPPORTED_ABIS));
        EngineDiagnostics.state("display.pixels", dm.widthPixels + "x" + dm.heightPixels);
        EngineDiagnostics.state("display.density", String.valueOf(dm.density));
    }

    private void sampleRuntimeState() {
        Runtime rt = Runtime.getRuntime();
        long javaUsed = rt.totalMemory() - rt.freeMemory();
        EngineDiagnostics.gauge("memory.java_used_mb", javaUsed / 1048576.0);
        EngineDiagnostics.gauge("memory.java_total_mb", rt.totalMemory() / 1048576.0);
        EngineDiagnostics.gauge("memory.java_max_mb", rt.maxMemory() / 1048576.0);
        EngineDiagnostics.gauge("memory.native_heap_mb",
                Debug.getNativeHeapAllocatedSize() / 1048576.0);
        EngineDiagnostics.gauge("process.uptime_ms", SystemClock.uptimeMillis());

        ActivityManager am = (ActivityManager) context.getSystemService(Context.ACTIVITY_SERVICE);
        if (am != null) {
            ActivityManager.MemoryInfo mi = new ActivityManager.MemoryInfo();
            am.getMemoryInfo(mi);
            EngineDiagnostics.gauge("memory.system_available_mb", mi.availMem / 1048576.0);
            EngineDiagnostics.gauge("memory.system_threshold_mb", mi.threshold / 1048576.0);
            EngineDiagnostics.state("memory.low", String.valueOf(mi.lowMemory));
        }

        if (Build.VERSION.SDK_INT >= 29) {
            PowerManager pm = (PowerManager) context.getSystemService(Context.POWER_SERVICE);
            if (pm != null) {
                EngineDiagnostics.gauge("device.thermal_status", pm.getCurrentThermalStatus());
            }
        }
    }

    private void writeManifest(File file, EngineDiagnostics.Snapshot s,
                               String reason, Throwable crash) throws IOException {
        try (BufferedWriter w = new BufferedWriter(new FileWriter(file))) {
            w.write("{\n");
            w.write("  \"schema\":\"pocketsculpt-engine-dump-v1\",\n");
            w.write("  \"generated_at\":\"" + esc(isoTime(s.capturedWallMillis)) + "\",\n");
            w.write("  \"reason\":\"" + esc(reason) + "\",\n");
            w.write("  \"dev_mode\":" + BuildConfig.ENGINE_DIAGNOSTICS + ",\n");
            w.write("  \"session_elapsed_ns\":" + s.sessionElapsedNanos + ",\n");
            w.write("  \"event_capacity\":" + EngineDiagnostics.EVENT_CAPACITY + ",\n");
            w.write("  \"events_retained\":" + s.events.size() + ",\n");
            w.write("  \"events_dropped\":" + s.droppedEvents + ",\n");
            w.write("  \"crash\":" + (crash == null ? "null" :
                    "{\"type\":\"" + esc(crash.getClass().getName())
                            + "\",\"message\":\"" + esc(String.valueOf(crash.getMessage())) + "\"}") + ",\n");
            writeLongMap(w, "counters", s.counters, true);
            writeDoubleMap(w, "gauges", s.gauges, true);
            writeStringMap(w, "state", s.state, false);
            w.write("}\n");
        }
    }

    private static void writeEvents(File file, EngineDiagnostics.Snapshot s) throws IOException {
        try (BufferedWriter w = new BufferedWriter(new FileWriter(file))) {
            for (EngineDiagnostics.Event e : s.events) {
                w.write("{\"seq\":" + e.sequence
                        + ",\"elapsed_ns\":" + e.elapsedNanos
                        + ",\"thread_id\":" + e.threadId
                        + ",\"thread\":\"" + esc(e.threadName)
                        + "\",\"category\":\"" + esc(e.category)
                        + "\",\"name\":\"" + esc(e.name)
                        + "\",\"detail\":\"" + esc(e.detail)
                        + "\"}\n");
            }
        }
    }

    private static void writeThreads(File file) throws IOException {
        try (BufferedWriter w = new BufferedWriter(new FileWriter(file))) {
            for (Map.Entry<Thread, StackTraceElement[]> entry
                    : Thread.getAllStackTraces().entrySet()) {
                Thread t = entry.getKey();
                w.write("\"" + t.getName() + "\" id=" + t.getId()
                        + " state=" + t.getState()
                        + " priority=" + t.getPriority()
                        + " daemon=" + t.isDaemon() + "\n");
                for (StackTraceElement frame : entry.getValue()) {
                    w.write("    at " + frame + "\n");
                }
                w.write("\n");
            }
        }
    }

    private static void writeCrash(File file, Throwable crash) throws IOException {
        StringWriter sw = new StringWriter();
        crash.printStackTrace(new PrintWriter(sw));
        try (FileWriter w = new FileWriter(file)) {
            w.write(sw.toString());
        }
    }

    private static void writeSystem(File file, EngineDiagnostics.Snapshot s,
                                    String reason) throws IOException {
        try (BufferedWriter w = new BufferedWriter(new FileWriter(file))) {
            w.write("PocketSculpt deep engine diagnostics\n");
            w.write("Reason: " + reason + "\n");
            w.write("Captured: " + isoTime(s.capturedWallMillis) + "\n");
            w.write("Session ns: " + s.sessionElapsedNanos + "\n");
            w.write("Events retained: " + s.events.size()
                    + " dropped: " + s.droppedEvents + "\n\n");

            w.write("[STATE]\n");
            for (Map.Entry<String, String> e : s.state.entrySet()) {
                w.write(e.getKey() + "=" + e.getValue() + "\n");
            }
            w.write("\n[GAUGES]\n");
            for (Map.Entry<String, Double> e : s.gauges.entrySet()) {
                w.write(e.getKey() + "=" + e.getValue() + "\n");
            }
            w.write("\n[COUNTERS]\n");
            for (Map.Entry<String, Long> e : s.counters.entrySet()) {
                w.write(e.getKey() + "=" + e.getValue() + "\n");
            }
        }
    }

    private static void writeLongMap(BufferedWriter w, String name,
                                     Map<String, Long> map, boolean commaAfter) throws IOException {
        w.write("  \"" + name + "\":{");
        boolean first = true;
        for (Map.Entry<String, Long> e : map.entrySet()) {
            if (!first) w.write(",");
            first = false;
            w.write("\"" + esc(e.getKey()) + "\":" + e.getValue());
        }
        w.write("}" + (commaAfter ? "," : "") + "\n");
    }

    private static void writeDoubleMap(BufferedWriter w, String name,
                                       Map<String, Double> map, boolean commaAfter) throws IOException {
        w.write("  \"" + name + "\":{");
        boolean first = true;
        for (Map.Entry<String, Double> e : map.entrySet()) {
            if (!first) w.write(",");
            first = false;
            w.write("\"" + esc(e.getKey()) + "\":" + e.getValue());
        }
        w.write("}" + (commaAfter ? "," : "") + "\n");
    }

    private static void writeStringMap(BufferedWriter w, String name,
                                       Map<String, String> map, boolean commaAfter) throws IOException {
        w.write("  \"" + name + "\":{");
        boolean first = true;
        for (Map.Entry<String, String> e : map.entrySet()) {
            if (!first) w.write(",");
            first = false;
            w.write("\"" + esc(e.getKey()) + "\":\"" + esc(e.getValue()) + "\"");
        }
        w.write("}" + (commaAfter ? "," : "") + "\n");
    }

    private static String isoTime(long millis) {
        SimpleDateFormat f = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'", Locale.US);
        f.setTimeZone(TimeZone.getTimeZone("UTC"));
        return f.format(new Date(millis));
    }

    private static String fileStamp(long millis) {
        SimpleDateFormat f = new SimpleDateFormat("yyyy-MM-dd'T'HH-mm-ss-SSS'Z'", Locale.US);
        f.setTimeZone(TimeZone.getTimeZone("UTC"));
        return f.format(new Date(millis));
    }

    private static String sanitize(String s) {
        if (s == null || s.isEmpty()) return "dump";
        return s.replaceAll("[^A-Za-z0-9._-]+", "_");
    }

    private static String esc(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\n", "\\n")
                .replace("\r", "\\r")
                .replace("\t", "\\t");
    }
}

package com.fallpoint.pocketsculpt;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.security.MessageDigest;
import java.util.Arrays;

/**
 * CABrush AVS 0.1 source of truth.
 *
 * The sculpt is a sparse signed-distance field stored in 8x8x8 sample bricks.
 * Triangles are disposable render cache and never own sculpt state.
 */
final class AvsVolume {
    static final int BRICK_SIZE = 8;
    static final int SAMPLES_PER_BRICK = BRICK_SIZE * BRICK_SIZE * BRICK_SIZE;
    static final int MAX_BRICKS = 12_000;

    static final float VOXEL_SIZE = 0.045f;
    static final float Q_PER_VOXEL = 8192.0f;
    static final short FAR_OUTSIDE = (short)32760;
    static final float BAND_WORLD = (32760.0f / Q_PER_VOXEL) * VOXEL_SIZE;

    static final class Brick {
        final int bx, by, bz;
        final short[] sdf = new short[SAMPLES_PER_BRICK];
        boolean dirty = true;
        long revision = 1L;

        Brick(int bx, int by, int bz) {
            this.bx = bx; this.by = by; this.bz = bz;
            Arrays.fill(sdf, FAR_OUTSIDE);
        }
    }

    static final class RayHit {
        float x, y, z;
        float nx, ny, nz;
        float t;
        boolean hit;
        int marchSteps;
        int refineSteps;
        long durationNanos;

        RayHit clear() {
            hit = false;
            x = y = z = nx = ny = nz = t = 0f;
            marchSteps = 0;
            refineSteps = 0;
            durationNanos = 0L;
            return this;
        }
    }

    static final class BrushResult {
        boolean changed;
        int changedSamples;
        int touchedBricks;
        int allocatedBricks;
        float centerX, centerY, centerZ;
        float effectiveDepth;
        int testedSamples;
        int candidateSamples;
        long durationNanos;
        long fieldVersionBefore;
        long fieldVersionAfter;
    }

    static final class Stats {
        final int bricks;
        final long sampleBytes;
        final long negativeSamples;
        final float minX, minY, minZ, maxX, maxY, maxZ;

        Stats(int bricks, long sampleBytes, long negativeSamples,
              float minX, float minY, float minZ,
              float maxX, float maxY, float maxZ) {
            this.bricks = bricks;
            this.sampleBytes = sampleBytes;
            this.negativeSamples = negativeSamples;
            this.minX = minX; this.minY = minY; this.minZ = minZ;
            this.maxX = maxX; this.maxY = maxY; this.maxZ = maxZ;
        }
    }

    private final PrimitiveLongIntMap brickLookup = new PrimitiveLongIntMap(512);
    private Brick[] bricks = new Brick[256];
    private int brickCount;

    long fieldVersion = 1L;
    long allocationVersion = 1L;

    private int minBx = Integer.MAX_VALUE, minBy = Integer.MAX_VALUE, minBz = Integer.MAX_VALUE;
    private int maxBx = Integer.MIN_VALUE, maxBy = Integer.MIN_VALUE, maxBz = Integer.MIN_VALUE;

    private int[] changedBrickIds = new int[128];
    private int changedBrickCount;
    private int[] changedStamp = new int[256];
    private int stampGeneration = 1;

    private AvsVolume() {}

    static AvsVolume createSphere(float radius) {
        long diagStart = EngineDiagnostics.nowNanos();
        if (!(radius > 0f) || !Float.isFinite(radius)) {
            throw new IllegalArgumentException("radius");
        }
        AvsVolume v = new AvsVolume();
        float pad = BAND_WORLD + VOXEL_SIZE * 2f;
        int minG = floorGrid(-radius - pad);
        int maxG = ceilGrid(radius + pad);
        int minB = Math.floorDiv(minG, BRICK_SIZE) - 1;
        int maxB = Math.floorDiv(maxG, BRICK_SIZE) + 1;

        for (int bz = minB; bz <= maxB; bz++) {
            for (int by = minB; by <= maxB; by++) {
                for (int bx = minB; bx <= maxB; bx++) {
                    Brick b = v.ensureBrick(bx, by, bz);
                    int baseX = bx * BRICK_SIZE;
                    int baseY = by * BRICK_SIZE;
                    int baseZ = bz * BRICK_SIZE;
                    for (int lz = 0; lz < BRICK_SIZE; lz++) {
                        int gz = baseZ + lz;
                        float z = gz * VOXEL_SIZE;
                        for (int ly = 0; ly < BRICK_SIZE; ly++) {
                            int gy = baseY + ly;
                            float y = gy * VOXEL_SIZE;
                            for (int lx = 0; lx < BRICK_SIZE; lx++) {
                                int gx = baseX + lx;
                                float x = gx * VOXEL_SIZE;
                                float d = (float)Math.sqrt(x*x + y*y + z*z) - radius;
                                b.sdf[index(lx, ly, lz)] = encode(d);
                            }
                        }
                    }
                    b.dirty = true;
                }
            }
        }
        v.fieldVersion++;
        v.markAllDirty();
        if (EngineDiagnostics.isEnabled()) {
            EngineDiagnostics.state("avs.voxel_size", String.valueOf(VOXEL_SIZE));
            EngineDiagnostics.state("avs.brick_size", String.valueOf(BRICK_SIZE));
            EngineDiagnostics.state("avs.max_bricks", String.valueOf(MAX_BRICKS));
            EngineDiagnostics.timed("avs", "create_sphere", diagStart,
                    "radius=" + radius + " bricks=" + v.brickCount
                            + " field_version=" + v.fieldVersion);
        }
        return v;
    }

    int brickCount() { return brickCount; }

    Brick brick(int id) {
        if (id < 0 || id >= brickCount) return null;
        return bricks[id];
    }

    int brickId(int bx, int by, int bz) {
        return brickLookup.get(brickKey(bx, by, bz), -1);
    }

    boolean isBrickDirty(int id) {
        Brick b = brick(id);
        return b != null && b.dirty;
    }

    void clearBrickDirty(int id) {
        Brick b = brick(id);
        if (b != null) b.dirty = false;
    }

    int dirtyBrickCount() {
        int n = 0;
        for (int i = 0; i < brickCount; i++) if (bricks[i].dirty) n++;
        return n;
    }

    void markAllDirty() {
        for (int i = 0; i < brickCount; i++) {
            bricks[i].dirty = true;
            bricks[i].revision++;
        }
    }

    float sampleGrid(int gx, int gy, int gz) {
        int bx = Math.floorDiv(gx, BRICK_SIZE);
        int by = Math.floorDiv(gy, BRICK_SIZE);
        int bz = Math.floorDiv(gz, BRICK_SIZE);
        int id = brickId(bx, by, bz);
        if (id < 0) return decode(FAR_OUTSIDE);
        int lx = Math.floorMod(gx, BRICK_SIZE);
        int ly = Math.floorMod(gy, BRICK_SIZE);
        int lz = Math.floorMod(gz, BRICK_SIZE);
        return decode(bricks[id].sdf[index(lx, ly, lz)]);
    }

    short sampleGridQuantized(int gx, int gy, int gz) {
        int bx = Math.floorDiv(gx, BRICK_SIZE);
        int by = Math.floorDiv(gy, BRICK_SIZE);
        int bz = Math.floorDiv(gz, BRICK_SIZE);
        int id = brickId(bx, by, bz);
        if (id < 0) return FAR_OUTSIDE;
        int lx = Math.floorMod(gx, BRICK_SIZE);
        int ly = Math.floorMod(gy, BRICK_SIZE);
        int lz = Math.floorMod(gz, BRICK_SIZE);
        return bricks[id].sdf[index(lx, ly, lz)];
    }

    float sample(float x, float y, float z) {
        float gx = x / VOXEL_SIZE;
        float gy = y / VOXEL_SIZE;
        float gz = z / VOXEL_SIZE;
        int ix = fastFloor(gx);
        int iy = fastFloor(gy);
        int iz = fastFloor(gz);
        float tx = gx - ix, ty = gy - iy, tz = gz - iz;

        float c000 = sampleGrid(ix, iy, iz);
        float c100 = sampleGrid(ix + 1, iy, iz);
        float c010 = sampleGrid(ix, iy + 1, iz);
        float c110 = sampleGrid(ix + 1, iy + 1, iz);
        float c001 = sampleGrid(ix, iy, iz + 1);
        float c101 = sampleGrid(ix + 1, iy, iz + 1);
        float c011 = sampleGrid(ix, iy + 1, iz + 1);
        float c111 = sampleGrid(ix + 1, iy + 1, iz + 1);

        float x00 = lerp(c000, c100, tx);
        float x10 = lerp(c010, c110, tx);
        float x01 = lerp(c001, c101, tx);
        float x11 = lerp(c011, c111, tx);
        float y0 = lerp(x00, x10, ty);
        float y1 = lerp(x01, x11, ty);
        return lerp(y0, y1, tz);
    }

    void gradient(float x, float y, float z, float[] out) {
        float e = VOXEL_SIZE;
        float dx = sample(x + e, y, z) - sample(x - e, y, z);
        float dy = sample(x, y + e, z) - sample(x, y - e, z);
        float dz = sample(x, y, z + e) - sample(x, y, z - e);
        float len = (float)Math.sqrt(dx*dx + dy*dy + dz*dz);
        if (len < 1e-8f || !Float.isFinite(len)) {
            out[0] = 0f; out[1] = 0f; out[2] = 1f;
        } else {
            out[0] = dx / len; out[1] = dy / len; out[2] = dz / len;
        }
    }

    RayHit raycast(float ox, float oy, float oz, float dx, float dy, float dz, RayHit out) {
        long diagStart = EngineDiagnostics.nowNanos();
        if (out == null) out = new RayHit();
        out.clear();
        float dlen = (float)Math.sqrt(dx*dx + dy*dy + dz*dz);
        if (dlen < 1e-8f || brickCount == 0) {
            finishRayTelemetry(out, diagStart, "invalid-or-empty", ox, oy, oz, dx, dy, dz);
            return out;
        }
        dx /= dlen; dy /= dlen; dz /= dlen;

        float minX = minBx * BRICK_SIZE * VOXEL_SIZE - VOXEL_SIZE;
        float minY = minBy * BRICK_SIZE * VOXEL_SIZE - VOXEL_SIZE;
        float minZ = minBz * BRICK_SIZE * VOXEL_SIZE - VOXEL_SIZE;
        float maxX = (maxBx + 1) * BRICK_SIZE * VOXEL_SIZE + VOXEL_SIZE;
        float maxY = (maxBy + 1) * BRICK_SIZE * VOXEL_SIZE + VOXEL_SIZE;
        float maxZ = (maxBz + 1) * BRICK_SIZE * VOXEL_SIZE + VOXEL_SIZE;

        float[] interval = rayBox(ox, oy, oz, dx, dy, dz, minX, minY, minZ, maxX, maxY, maxZ);
        if (interval == null) {
            finishRayTelemetry(out, diagStart, "box-miss", ox, oy, oz, dx, dy, dz);
            return out;
        }
        float t0 = Math.max(0f, interval[0]);
        float t1 = interval[1];
        if (!(t1 > t0)) {
            finishRayTelemetry(out, diagStart, "empty-interval", ox, oy, oz, dx, dy, dz);
            return out;
        }

        float step = VOXEL_SIZE * 0.45f;
        float prevT = t0;
        float prev = sample(ox + dx*prevT, oy + dy*prevT, oz + dz*prevT);

        for (float t = t0 + step; t <= t1 + step * 0.5f; t += step) {
            out.marchSteps++;
            float tt = Math.min(t, t1);
            float cur = sample(ox + dx*tt, oy + dy*tt, oz + dz*tt);
            if (prev > 0f && cur <= 0f) {
                float lo = prevT, hi = tt;
                for (int i = 0; i < 10; i++) {
                    out.refineSteps++;
                    float mid = (lo + hi) * 0.5f;
                    float mv = sample(ox + dx*mid, oy + dy*mid, oz + dz*mid);
                    if (mv > 0f) lo = mid; else hi = mid;
                }
                float hitT = (lo + hi) * 0.5f;
                out.t = hitT;
                out.x = ox + dx*hitT;
                out.y = oy + dy*hitT;
                out.z = oz + dz*hitT;
                float[] g = new float[3];
                gradient(out.x, out.y, out.z, g);
                out.nx = g[0]; out.ny = g[1]; out.nz = g[2];
                out.hit = true;
                finishRayTelemetry(out, diagStart, "hit", ox, oy, oz, dx, dy, dz);
                return out;
            }
            prev = cur;
            prevT = tt;
            if (tt >= t1) break;
        }
        finishRayTelemetry(out, diagStart, "field-miss", ox, oy, oz, dx, dy, dz);
        return out;
    }

    private void finishRayTelemetry(RayHit out, long startNanos, String result,
                                    float ox, float oy, float oz,
                                    float dx, float dy, float dz) {
        if (!EngineDiagnostics.isEnabled()) return;
        out.durationNanos = startNanos == 0L ? 0L : System.nanoTime() - startNanos;
        EngineDiagnostics.counter("avs.raycast.calls", 1L);
        EngineDiagnostics.counter("avs.raycast.march_steps", out.marchSteps);
        EngineDiagnostics.counter("avs.raycast.refine_steps", out.refineSteps);
        EngineDiagnostics.gauge("avs.raycast.last_ms", out.durationNanos / 1_000_000.0);
        EngineDiagnostics.record("raycast", result,
                "origin=" + ox + "," + oy + "," + oz
                        + " dir=" + dx + "," + dy + "," + dz
                        + " hit=" + out.hit
                        + " t=" + out.t
                        + " p=" + out.x + "," + out.y + "," + out.z
                        + " n=" + out.nx + "," + out.ny + "," + out.nz
                        + " march=" + out.marchSteps
                        + " refine=" + out.refineSteps
                        + " duration_ns=" + out.durationNanos);
        if (out.durationNanos > 50_000_000L) {
            EngineDiagnostics.anomaly("slow_raycast",
                    "duration_ns=" + out.durationNanos + " march=" + out.marchSteps
                            + " bricks=" + brickCount);
        }
    }

    BrushResult applyClay(float hitX, float hitY, float hitZ,
                           float nx, float ny, float nz,
                           float radius, float strength, BrushMode mode) {
        long diagStart = EngineDiagnostics.nowNanos();
        long beforeVersion = fieldVersion;
        BrushResult result = new BrushResult();
        result.fieldVersionBefore = beforeVersion;
        result.fieldVersionAfter = beforeVersion;

        if (mode == null || !(radius > VOXEL_SIZE * 0.5f) || !(strength > 0f)) {
            finishBrushTelemetry("clay-rejected", result, diagStart,
                    hitX, hitY, hitZ, radius, strength, mode);
            return result;
        }
        float nlen = (float)Math.sqrt(nx*nx + ny*ny + nz*nz);
        if (nlen < 1e-8f) {
            finishBrushTelemetry("clay-bad-normal", result, diagStart,
                    hitX, hitY, hitZ, radius, strength, mode);
            return result;
        }
        nx /= nlen; ny /= nlen; nz /= nlen;

        float depth = Math.max(VOXEL_SIZE * 0.45f, strength * 2.10f);
        depth = Math.min(depth, radius * 0.45f);
        float sign = mode == BrushMode.ADD ? 1f : -1f;

        // Clay is an oblate implicit blob: the slider Size controls the broad
        // tangent footprint while Strength controls shallow build/cut depth.
        // This avoids turning every dab into a full-radius sphere protrusion.
        float cx = hitX + nx * depth * 0.28f * sign;
        float cy = hitY + ny * depth * 0.28f * sign;
        float cz = hitZ + nz * depth * 0.28f * sign;

        BrushResult csg = applyEllipsoidCsg(
                cx, cy, cz, nx, ny, nz,
                radius, depth,
                mode == BrushMode.ADD
        );
        csg.centerX = cx; csg.centerY = cy; csg.centerZ = cz;
        csg.effectiveDepth = depth;
        csg.fieldVersionBefore = beforeVersion;
        csg.fieldVersionAfter = fieldVersion;
        finishBrushTelemetry("clay", csg, diagStart,
                hitX, hitY, hitZ, radius, strength, mode);
        return csg;
    }

    private void finishBrushTelemetry(String name, BrushResult r, long startNanos,
                                      float hitX, float hitY, float hitZ,
                                      float radius, float strength, BrushMode mode) {
        if (!EngineDiagnostics.isEnabled()) return;
        r.durationNanos = startNanos == 0L ? 0L : System.nanoTime() - startNanos;
        EngineDiagnostics.counter("avs.brush.calls", 1L);
        if (r.changed) EngineDiagnostics.counter("avs.brush.changed", 1L);
        EngineDiagnostics.counter("avs.brush.changed_samples", r.changedSamples);
        EngineDiagnostics.counter("avs.brush.touched_bricks", r.touchedBricks);
        EngineDiagnostics.counter("avs.brush.allocated_bricks", r.allocatedBricks);
        EngineDiagnostics.gauge("avs.brush.last_ms", r.durationNanos / 1_000_000.0);
        EngineDiagnostics.gauge("avs.brush.last_changed_samples", r.changedSamples);
        EngineDiagnostics.gauge("avs.brush.last_depth", r.effectiveDepth);
        boolean depthFloorDominant = strength * 2.10f < VOXEL_SIZE * 0.45f;
        EngineDiagnostics.state("brush.depth_floor_world", String.valueOf(VOXEL_SIZE * 0.45f));
        EngineDiagnostics.state("brush.depth_floor_dominant", String.valueOf(depthFloorDominant));
        EngineDiagnostics.state("avs.field_version", String.valueOf(fieldVersion));
        EngineDiagnostics.state("avs.brick_count", String.valueOf(brickCount));
        EngineDiagnostics.record("brush", name,
                "mode=" + String.valueOf(mode)
                        + " hit=" + hitX + "," + hitY + "," + hitZ
                        + " radius=" + radius
                        + " strength=" + strength
                        + " center=" + r.centerX + "," + r.centerY + "," + r.centerZ
                        + " depth=" + r.effectiveDepth
                        + " depth_floor_dominant=" + depthFloorDominant
                        + " changed=" + r.changed
                        + " changed_samples=" + r.changedSamples
                        + " tested_samples=" + r.testedSamples
                        + " candidate_samples=" + r.candidateSamples
                        + " touched_bricks=" + r.touchedBricks
                        + " allocated_bricks=" + r.allocatedBricks
                        + " field=" + r.fieldVersionBefore + "->" + r.fieldVersionAfter
                        + " duration_ns=" + r.durationNanos);

        if (r.durationNanos > 100_000_000L) {
            EngineDiagnostics.anomaly("slow_brush",
                    "duration_ns=" + r.durationNanos
                            + " tested=" + r.testedSamples
                            + " changed=" + r.changedSamples);
        }
        if (r.allocatedBricks > 256 || brickCount > (int)(MAX_BRICKS * 0.80f)) {
            EngineDiagnostics.anomaly("brick_growth",
                    "allocated_this_dab=" + r.allocatedBricks
                            + " total=" + brickCount + "/" + MAX_BRICKS);
        }
        if (r.changedSamples > 30_000) {
            EngineDiagnostics.anomaly("brush_sample_spike",
                    "changed_samples=" + r.changedSamples
                            + " radius=" + radius + " strength=" + strength);
        }
    }

    private BrushResult applyEllipsoidCsg(float cx, float cy, float cz,
                                           float nx, float ny, float nz,
                                           float tangentRadius, float normalRadius,
                                           boolean add) {
        long diagStart = EngineDiagnostics.nowNanos();
        BrushResult result = new BrushResult();
        result.fieldVersionBefore = fieldVersion;
        float reach = tangentRadius + BAND_WORLD;
        changedBrickCount = 0;
        int stamp = nextStamp();
        int beforeBricks = brickCount;

        int minGx = floorGrid(cx - reach), maxGx = ceilGrid(cx + reach);
        int minGy = floorGrid(cy - reach), maxGy = ceilGrid(cy + reach);
        int minGz = floorGrid(cz - reach), maxGz = ceilGrid(cz + reach);
        allocateRegion(minGx,maxGx,minGy,maxGy,minGz,maxGz);

        int changedSamples = 0;
        float invT = 1f / Math.max(tangentRadius, 1e-6f);
        float invN = 1f / Math.max(normalRadius, 1e-6f);
        float distanceScale = Math.min(tangentRadius, normalRadius);

        for (int gz=minGz; gz<=maxGz; gz++) {
            float z=gz*VOXEL_SIZE;
            for (int gy=minGy; gy<=maxGy; gy++) {
                float y=gy*VOXEL_SIZE;
                for (int gx=minGx; gx<=maxGx; gx++) {
                    result.testedSamples++;
                    float x=gx*VOXEL_SIZE;
                    float dx=x-cx,dy=y-cy,dz=z-cz;
                    float axial=dx*nx+dy*ny+dz*nz;
                    float d2=dx*dx+dy*dy+dz*dz;
                    float tangent2=Math.max(0f,d2-axial*axial);
                    float q=(float)Math.sqrt(tangent2*invT*invT + axial*axial*invN*invN)-1f;
                    float brush=q*distanceScale;
                    if (brush > BAND_WORLD) continue;
                    result.candidateSamples++;
                    changedSamples += applySampleCsg(gx,gy,gz,brush,add,stamp);
                }
            }
        }
        if (changedSamples>0) {
            fieldVersion++;
            markNeighborhoodDirty();
            result.changed=true;
        }
        result.changedSamples=changedSamples;
        result.touchedBricks=changedBrickCount;
        result.allocatedBricks=brickCount-beforeBricks;
        result.fieldVersionAfter=fieldVersion;
        if (EngineDiagnostics.isEnabled()) {
            result.durationNanos = diagStart == 0L ? 0L : System.nanoTime() - diagStart;
            EngineDiagnostics.counter("avs.csg.ellipsoid.calls", 1L);
            EngineDiagnostics.counter("avs.csg.ellipsoid.tested_samples", result.testedSamples);
            EngineDiagnostics.counter("avs.csg.ellipsoid.candidate_samples", result.candidateSamples);
            EngineDiagnostics.gauge("avs.csg.ellipsoid.last_ms", result.durationNanos / 1_000_000.0);
            EngineDiagnostics.record("csg", add ? "ellipsoid-union" : "ellipsoid-subtract",
                    "center=" + cx + "," + cy + "," + cz
                            + " tangent_radius=" + tangentRadius
                            + " normal_radius=" + normalRadius
                            + " tested=" + result.testedSamples
                            + " candidates=" + result.candidateSamples
                            + " changed=" + result.changedSamples
                            + " touched_bricks=" + result.touchedBricks
                            + " allocated_bricks=" + result.allocatedBricks
                            + " duration_ns=" + result.durationNanos);
        }
        return result;
    }

    BrushResult applySphereCsg(float cx, float cy, float cz, float radius, boolean add) {
        long diagStart = EngineDiagnostics.nowNanos();
        BrushResult result = new BrushResult();
        result.fieldVersionBefore = fieldVersion;
        if (!(radius > 0f) || !Float.isFinite(radius)) return result;

        changedBrickCount = 0;
        int stamp = nextStamp();
        int beforeBricks = brickCount;

        float reach = radius + BAND_WORLD;
        int minGx = floorGrid(cx - reach), maxGx = ceilGrid(cx + reach);
        int minGy = floorGrid(cy - reach), maxGy = ceilGrid(cy + reach);
        int minGz = floorGrid(cz - reach), maxGz = ceilGrid(cz + reach);

        allocateRegion(minGx,maxGx,minGy,maxGy,minGz,maxGz);

        int changedSamples = 0;
        for (int gz = minGz; gz <= maxGz; gz++) {
            float z = gz * VOXEL_SIZE;
            for (int gy = minGy; gy <= maxGy; gy++) {
                float y = gy * VOXEL_SIZE;
                for (int gx = minGx; gx <= maxGx; gx++) {
                    result.testedSamples++;
                    float x = gx * VOXEL_SIZE;
                    float dx = x - cx, dy = y - cy, dz = z - cz;
                    float brush = (float)Math.sqrt(dx*dx + dy*dy + dz*dz) - radius;
                    if (Math.abs(brush) > BAND_WORLD && brush > 0f) continue;
                    result.candidateSamples++;
                    changedSamples += applySampleCsg(gx,gy,gz,brush,add,stamp);
                }
            }
        }

        if (changedSamples > 0) {
            fieldVersion++;
            markNeighborhoodDirty();
            result.changed = true;
        }
        result.changedSamples = changedSamples;
        result.touchedBricks = changedBrickCount;
        result.allocatedBricks = brickCount - beforeBricks;
        result.fieldVersionAfter = fieldVersion;
        if (EngineDiagnostics.isEnabled()) {
            result.durationNanos = diagStart == 0L ? 0L : System.nanoTime() - diagStart;
            EngineDiagnostics.counter("avs.csg.sphere.calls", 1L);
            EngineDiagnostics.counter("avs.csg.sphere.tested_samples", result.testedSamples);
            EngineDiagnostics.counter("avs.csg.sphere.candidate_samples", result.candidateSamples);
            EngineDiagnostics.gauge("avs.csg.sphere.last_ms", result.durationNanos / 1_000_000.0);
            EngineDiagnostics.record("csg", add ? "sphere-union" : "sphere-subtract",
                    "center=" + cx + "," + cy + "," + cz
                            + " radius=" + radius
                            + " tested=" + result.testedSamples
                            + " candidates=" + result.candidateSamples
                            + " changed=" + result.changedSamples
                            + " touched_bricks=" + result.touchedBricks
                            + " allocated_bricks=" + result.allocatedBricks
                            + " duration_ns=" + result.durationNanos);
        }
        return result;
    }

    private void allocateRegion(int minGx,int maxGx,int minGy,int maxGy,int minGz,int maxGz) {
        int minBBx=Math.floorDiv(minGx,BRICK_SIZE)-1, maxBBx=Math.floorDiv(maxGx,BRICK_SIZE)+1;
        int minBBy=Math.floorDiv(minGy,BRICK_SIZE)-1, maxBBy=Math.floorDiv(maxGy,BRICK_SIZE)+1;
        int minBBz=Math.floorDiv(minGz,BRICK_SIZE)-1, maxBBz=Math.floorDiv(maxGz,BRICK_SIZE)+1;
        for(int bz=minBBz;bz<=maxBBz;bz++) for(int by=minBBy;by<=maxBBy;by++) for(int bx=minBBx;bx<=maxBBx;bx++) {
            ensureBrick(bx,by,bz);
        }
    }

    private int applySampleCsg(int gx,int gy,int gz,float brush,boolean add,int stamp) {
        int bx=Math.floorDiv(gx,BRICK_SIZE),by=Math.floorDiv(gy,BRICK_SIZE),bz=Math.floorDiv(gz,BRICK_SIZE);
        int id=brickId(bx,by,bz);
        Brick b=bricks[id];
        int si=index(Math.floorMod(gx,BRICK_SIZE),Math.floorMod(gy,BRICK_SIZE),Math.floorMod(gz,BRICK_SIZE));
        float old=decode(b.sdf[si]);
        float next=add?Math.min(old,brush):Math.max(old,-brush);
        short q=encode(next);
        if(q==b.sdf[si]) return 0;
        b.sdf[si]=q;
        if(changedStamp[id]!=stamp){changedStamp[id]=stamp;addChangedBrick(id);}
        return 1;
    }

    Stats stats() {
        long negative = 0;
        for (int b = 0; b < brickCount; b++) {
            for (short q : bricks[b].sdf) if (q < 0) negative++;
        }
        float minX = minBx == Integer.MAX_VALUE ? 0f : minBx * BRICK_SIZE * VOXEL_SIZE;
        float minY = minBy == Integer.MAX_VALUE ? 0f : minBy * BRICK_SIZE * VOXEL_SIZE;
        float minZ = minBz == Integer.MAX_VALUE ? 0f : minBz * BRICK_SIZE * VOXEL_SIZE;
        float maxX = maxBx == Integer.MIN_VALUE ? 0f : (maxBx + 1) * BRICK_SIZE * VOXEL_SIZE;
        float maxY = maxBy == Integer.MIN_VALUE ? 0f : (maxBy + 1) * BRICK_SIZE * VOXEL_SIZE;
        float maxZ = maxBz == Integer.MIN_VALUE ? 0f : (maxBz + 1) * BRICK_SIZE * VOXEL_SIZE;
        return new Stats(brickCount, (long)brickCount * SAMPLES_PER_BRICK * 2L, negative,
                minX, minY, minZ, maxX, maxY, maxZ);
    }

    String fieldHash() {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            Integer[] ids = new Integer[brickCount];
            for (int i = 0; i < brickCount; i++) ids[i] = i;
            Arrays.sort(ids, (a,b) -> {
                Brick A = bricks[a], B = bricks[b];
                if (A.bx != B.bx) return Integer.compare(A.bx, B.bx);
                if (A.by != B.by) return Integer.compare(A.by, B.by);
                return Integer.compare(A.bz, B.bz);
            });
            ByteBuffer buf = ByteBuffer.allocate(12 + SAMPLES_PER_BRICK * 2).order(ByteOrder.LITTLE_ENDIAN);
            for (int id : ids) {
                Brick b = bricks[id];
                buf.clear();
                buf.putInt(b.bx).putInt(b.by).putInt(b.bz);
                for (short q : b.sdf) buf.putShort(q);
                md.update(buf.array(), 0, buf.position());
            }
            StringBuilder sb = new StringBuilder();
            for (byte v : md.digest()) sb.append(String.format("%02x", v & 0xff));
            return sb.toString();
        } catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }

    AvsSnapshot snapshot() {
        return AvsSnapshot.capture(this);
    }

    void restore(AvsSnapshot snapshot) {
        long diagStart = EngineDiagnostics.nowNanos();
        if (snapshot == null) throw new IllegalArgumentException("snapshot");
        brickLookup.clear();
        brickCount = 0;
        minBx = minBy = minBz = Integer.MAX_VALUE;
        maxBx = maxBy = maxBz = Integer.MIN_VALUE;
        ensureBrickArray(snapshot.brickCount);
        ensureStampCapacity(snapshot.brickCount);

        for (int i = 0; i < snapshot.brickCount; i++) {
            Brick b = ensureBrick(snapshot.bx[i], snapshot.by[i], snapshot.bz[i]);
            System.arraycopy(snapshot.samples, i * SAMPLES_PER_BRICK, b.sdf, 0, SAMPLES_PER_BRICK);
            b.dirty = true;
            b.revision++;
        }
        fieldVersion++;
        allocationVersion++;
        markAllDirty();
        if (EngineDiagnostics.isEnabled()) {
            EngineDiagnostics.timed("avs", "restore_snapshot", diagStart,
                    "bricks=" + brickCount + " field_version=" + fieldVersion);
            EngineDiagnostics.state("avs.brick_count", String.valueOf(brickCount));
            EngineDiagnostics.state("avs.field_version", String.valueOf(fieldVersion));
        }
    }

    private Brick ensureBrick(int bx, int by, int bz) {
        long key = brickKey(bx, by, bz);
        int existing = brickLookup.get(key, -1);
        if (existing >= 0) return bricks[existing];
        if (brickCount >= MAX_BRICKS) throw new IllegalStateException("AVS brick budget exceeded");
        ensureBrickArray(brickCount + 1);
        ensureStampCapacity(brickCount + 1);
        int id = brickCount++;
        Brick b = new Brick(bx, by, bz);
        bricks[id] = b;
        brickLookup.put(key, id, -1);
        minBx = Math.min(minBx, bx); minBy = Math.min(minBy, by); minBz = Math.min(minBz, bz);
        maxBx = Math.max(maxBx, bx); maxBy = Math.max(maxBy, by); maxBz = Math.max(maxBz, bz);
        allocationVersion++;
        if (EngineDiagnostics.isEnabled()) {
            EngineDiagnostics.counter("avs.bricks_allocated", 1L);
            EngineDiagnostics.gauge("avs.brick_count", brickCount);
            if (brickCount == MAX_BRICKS) {
                EngineDiagnostics.anomaly("brick_budget_exhausted",
                        "brick_count=" + brickCount + " max=" + MAX_BRICKS);
            }
        }
        return b;
    }

    private void markNeighborhoodDirty() {
        for (int i = 0; i < changedBrickCount; i++) {
            Brick c = bricks[changedBrickIds[i]];
            for (int dz = -1; dz <= 1; dz++) {
                for (int dy = -1; dy <= 1; dy++) {
                    for (int dx = -1; dx <= 1; dx++) {
                        int id = brickId(c.bx + dx, c.by + dy, c.bz + dz);
                        if (id >= 0) {
                            Brick b = bricks[id];
                            b.dirty = true;
                            b.revision++;
                        }
                    }
                }
            }
        }
    }

    private void addChangedBrick(int id) {
        if (changedBrickCount == changedBrickIds.length) {
            changedBrickIds = Arrays.copyOf(changedBrickIds, changedBrickIds.length * 2);
        }
        changedBrickIds[changedBrickCount++] = id;
    }

    private int nextStamp() {
        if (stampGeneration == Integer.MAX_VALUE) {
            Arrays.fill(changedStamp, 0);
            stampGeneration = 1;
        }
        return stampGeneration++;
    }

    private void ensureBrickArray(int needed) {
        if (bricks.length >= needed) return;
        int cap = bricks.length;
        while (cap < needed) cap = cap + cap / 2 + 64;
        bricks = Arrays.copyOf(bricks, cap);
    }

    private void ensureStampCapacity(int needed) {
        if (changedStamp.length >= needed) return;
        int cap = changedStamp.length;
        while (cap < needed) cap = cap + cap / 2 + 64;
        changedStamp = Arrays.copyOf(changedStamp, cap);
    }

    private static int index(int x, int y, int z) {
        return x + BRICK_SIZE * (y + BRICK_SIZE * z);
    }

    static short encode(float worldDistance) {
        float q = worldDistance / VOXEL_SIZE * Q_PER_VOXEL;
        int qi = Math.round(q);
        if (qi == 0) qi = worldDistance < 0f ? -1 : 1;
        if (qi > 32760) qi = 32760;
        if (qi < -32760) qi = -32760;
        return (short)qi;
    }

    static float decode(short q) {
        return (q / Q_PER_VOXEL) * VOXEL_SIZE;
    }

    private static long brickKey(int bx, int by, int bz) {
        final int bias = 1 << 20;
        long x = (bx + bias) & 0x1fffffL;
        long y = (by + bias) & 0x1fffffL;
        long z = (bz + bias) & 0x1fffffL;
        return (x << 42) | (y << 21) | z;
    }

    private static float[] rayBox(float ox, float oy, float oz, float dx, float dy, float dz,
                                  float minX, float minY, float minZ,
                                  float maxX, float maxY, float maxZ) {
        float tmin = -Float.MAX_VALUE;
        float tmax = Float.MAX_VALUE;
        float[] o = {ox, oy, oz};
        float[] d = {dx, dy, dz};
        float[] mn = {minX, minY, minZ};
        float[] mx = {maxX, maxY, maxZ};
        for (int a = 0; a < 3; a++) {
            if (Math.abs(d[a]) < 1e-8f) {
                if (o[a] < mn[a] || o[a] > mx[a]) return null;
                continue;
            }
            float inv = 1f / d[a];
            float t0 = (mn[a] - o[a]) * inv;
            float t1 = (mx[a] - o[a]) * inv;
            if (t0 > t1) { float tmp = t0; t0 = t1; t1 = tmp; }
            tmin = Math.max(tmin, t0);
            tmax = Math.min(tmax, t1);
            if (tmax < tmin) return null;
        }
        return new float[]{tmin, tmax};
    }

    private static int floorGrid(float world) {
        return fastFloor(world / VOXEL_SIZE);
    }

    private static int ceilGrid(float world) {
        return (int)Math.ceil(world / VOXEL_SIZE);
    }

    private static int fastFloor(float v) {
        int i = (int)v;
        return v < i ? i - 1 : i;
    }

    private static float lerp(float a, float b, float t) {
        return a + (b - a) * t;
    }
}

package com.fallpoint.pocketsculpt;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Disposable AVS render cache.
 *
 * Surface Truth 0.1.1 rules:
 * - every grid cube uses the same six-tetrahedra Freudenthal split
 * - adjacent cubes therefore share the same face diagonals
 * - edge intersections are computed from canonically ordered global lattice
 *   endpoints, so a seam vertex is bit-identical even when rebuilt by a
 *   neighboring chunk
 * - triangle winding is derived from the exact linear scalar gradient of the
 *   tetrahedron, never from noisy post-CSG shading normals
 * - positive SDF means outside, so triangle geometric normals always point in
 *   the direction of increasing field value
 * - render normals are shading data only and can never decide topology/winding
 *
 * The signed-distance volume remains the only sculpt truth. These chunks may be
 * dropped and rebuilt at any time.
 */
final class AvsSurfaceCache {
    static final class Chunk {
        final int brickId;
        final int bx, by, bz;
        final long revision;
        final float[] positions;
        final float[] normals;
        final short[] indices;
        final float minX, minY, minZ, maxX, maxY, maxZ;

        Chunk(int brickId, int bx, int by, int bz, long revision,
              float[] positions, float[] normals, short[] indices,
              float minX, float minY, float minZ,
              float maxX, float maxY, float maxZ) {
            this.brickId = brickId;
            this.bx = bx;
            this.by = by;
            this.bz = bz;
            this.revision = revision;
            this.positions = positions;
            this.normals = normals;
            this.indices = indices;
            this.minX = minX;
            this.minY = minY;
            this.minZ = minZ;
            this.maxX = maxX;
            this.maxY = maxY;
            this.maxZ = maxZ;
        }

        int triangleCount() { return indices.length / 3; }

        long estimatedBytes() {
            return (long) (positions.length + normals.length) * 4L
                    + (long) indices.length * 2L + 64L;
        }
    }

    static final class RenderPlan {
        Chunk[] chunks = new Chunk[0];
        long fieldVersion = Long.MIN_VALUE;
        long surfaceVersion;
        int rebuiltChunks;
        long rebuiltBytes;
        long rebuildNanos;
        int dirtyBefore;
        int totalTriangles;
        int totalVertices;

        long estimatedBytes() {
            long n = 0;
            for (Chunk c : chunks) n += c.estimatedBytes();
            return n;
        }
    }

    // Cube corner index = x + 2*y + 4*z. All six tetrahedra share 0 -> 7.
    // This is the same split in every cell, which guarantees matching face
    // diagonals on neighboring cubes/chunks.
    private static final int[][] TETS = {
            {0, 1, 3, 7},
            {0, 1, 5, 7},
            {0, 2, 3, 7},
            {0, 2, 6, 7},
            {0, 4, 5, 7},
            {0, 4, 6, 7}
    };

    private static final float FACE_AREA_EPS = 1.0e-14f;
    private static final float GRADIENT_EPS = 1.0e-10f;

    private final AvsVolume volume;
    private Chunk[] chunkByBrick = new Chunk[256];
    private final RenderPlan plan = new RenderPlan();
    private long nextRevision = 1L;
    private final float[] gradientScratch = new float[3];

    AvsSurfaceCache(AvsVolume volume) {
        this.volume = volume;
    }

    RenderPlan currentPlan() {
        if (plan.fieldVersion != volume.fieldVersion || volume.dirtyBrickCount() > 0) {
            rebuildDirty();
        }
        return plan;
    }

    void rebuildAll() {
        volume.markAllDirty();
        rebuildDirty();
    }

    private void rebuildDirty() {
        long diagStart = EngineDiagnostics.nowNanos();
        ensureChunkCapacity(volume.brickCount());
        int rebuilt = 0;
        long bytes = 0;
        int dirtyBefore = volume.dirtyBrickCount();

        for (int id = 0; id < volume.brickCount(); id++) {
            if (!volume.isBrickDirty(id)) continue;
            long chunkStart = EngineDiagnostics.nowNanos();
            Chunk c = buildChunk(id);
            if (EngineDiagnostics.isEnabled()) {
                long chunkNs = chunkStart == 0L ? 0L : System.nanoTime() - chunkStart;
                EngineDiagnostics.counter("surface.chunks_rebuilt", 1L);
                EngineDiagnostics.gauge("surface.last_chunk_ms", chunkNs / 1_000_000.0);
                EngineDiagnostics.record("surface", "chunk_rebuild",
                        "brick_id=" + id
                                + " coord=" + volume.brick(id).bx + ","
                                + volume.brick(id).by + "," + volume.brick(id).bz
                                + " vertices=" + (c == null ? 0 : c.positions.length / 3)
                                + " triangles=" + (c == null ? 0 : c.indices.length / 3)
                                + " bytes=" + (c == null ? 0 : c.estimatedBytes())
                                + " duration_ns=" + chunkNs);
            }
            chunkByBrick[id] = c;
            volume.clearBrickDirty(id);
            rebuilt++;
            if (c != null) bytes += c.estimatedBytes();
        }

        List<Chunk> live = new ArrayList<>();
        int triangles = 0;
        int vertices = 0;
        for (int i = 0; i < volume.brickCount(); i++) {
            Chunk c = chunkByBrick[i];
            if (c == null || c.indices.length == 0) continue;
            live.add(c);
            triangles += c.indices.length / 3;
            vertices += c.positions.length / 3;
        }

        plan.chunks = live.toArray(new Chunk[0]);
        plan.fieldVersion = volume.fieldVersion;
        plan.surfaceVersion++;
        plan.rebuiltChunks = rebuilt;
        plan.rebuiltBytes = bytes;
        plan.rebuildNanos = diagStart == 0L ? 0L : System.nanoTime() - diagStart;
        plan.dirtyBefore = dirtyBefore;
        plan.totalTriangles = triangles;
        plan.totalVertices = vertices;

        if (EngineDiagnostics.isEnabled()) {
            EngineDiagnostics.counter("surface.rebuild_passes", 1L);
            EngineDiagnostics.counter("surface.rebuilt_bytes", bytes);
            EngineDiagnostics.gauge("surface.rebuild.last_ms", plan.rebuildNanos / 1_000_000.0);
            EngineDiagnostics.gauge("surface.total_triangles", triangles);
            EngineDiagnostics.gauge("surface.total_vertices", vertices);
            EngineDiagnostics.gauge("surface.estimated_mb", plan.estimatedBytes() / 1048576.0);
            EngineDiagnostics.state("surface.field_version", String.valueOf(plan.fieldVersion));
            EngineDiagnostics.state("surface.surface_version", String.valueOf(plan.surfaceVersion));
            EngineDiagnostics.record("surface", "rebuild_pass",
                    "dirty_before=" + dirtyBefore
                            + " rebuilt=" + rebuilt
                            + " rebuilt_bytes=" + bytes
                            + " chunks=" + plan.chunks.length
                            + " vertices=" + vertices
                            + " triangles=" + triangles
                            + " estimated_bytes=" + plan.estimatedBytes()
                            + " duration_ns=" + plan.rebuildNanos);
            if (plan.rebuildNanos > 200_000_000L) {
                EngineDiagnostics.anomaly("slow_surface_rebuild",
                        "duration_ns=" + plan.rebuildNanos
                                + " rebuilt=" + rebuilt
                                + " triangles=" + triangles);
            }
            if (triangles > 1_000_000) {
                EngineDiagnostics.anomaly("triangle_growth",
                        "triangles=" + triangles + " vertices=" + vertices
                                + " chunks=" + plan.chunks.length);
            }
        }
    }

    private Chunk buildChunk(int brickId) {
        AvsVolume.Brick b = volume.brick(brickId);
        if (b == null) return null;

        int baseX = b.bx * AvsVolume.BRICK_SIZE;
        int baseY = b.by * AvsVolume.BRICK_SIZE;
        int baseZ = b.bz * AvsVolume.BRICK_SIZE;

        FloatList positions = new FloatList(4096);
        ShortList indices = new ShortList(8192);
        PrimitiveLongIntMap edgeVertex = new PrimitiveLongIntMap(2048);

        int[] pointId = new int[8];
        int[] gx = new int[8];
        int[] gy = new int[8];
        int[] gz = new int[8];
        float[] value = new float[8];
        float[] tetGradient = new float[3];

        for (int lz = 0; lz < AvsVolume.BRICK_SIZE; lz++) {
            for (int ly = 0; ly < AvsVolume.BRICK_SIZE; ly++) {
                for (int lx = 0; lx < AvsVolume.BRICK_SIZE; lx++) {
                    boolean negative = false;
                    boolean positive = false;

                    for (int c = 0; c < 8; c++) {
                        int cx = c & 1;
                        int cy = (c >> 1) & 1;
                        int cz = (c >> 2) & 1;
                        int plx = lx + cx;
                        int ply = ly + cy;
                        int plz = lz + cz;
                        pointId[c] = plx + 9 * (ply + 9 * plz);
                        gx[c] = baseX + plx;
                        gy[c] = baseY + ply;
                        gz[c] = baseZ + plz;
                        value[c] = volume.sampleGrid(gx[c], gy[c], gz[c]);
                        if (value[c] < 0f) negative = true;
                        else positive = true;
                    }

                    if (!(negative && positive)) continue;
                    for (int[] tet : TETS) {
                        polygonizeTet(tet, pointId, gx, gy, gz, value,
                                tetGradient, edgeVertex, positions, indices);
                    }
                }
            }
        }

        if (indices.size == 0) {
            return new Chunk(brickId, b.bx, b.by, b.bz, nextRevision++,
                    new float[0], new float[0], new short[0],
                    0f, 0f, 0f, 0f, 0f, 0f);
        }

        float[] p = Arrays.copyOf(positions.data, positions.size);
        short[] ii = Arrays.copyOf(indices.data, indices.size);
        float[] n = buildNormals(p, ii);

        float minX = Float.POSITIVE_INFINITY;
        float minY = Float.POSITIVE_INFINITY;
        float minZ = Float.POSITIVE_INFINITY;
        float maxX = Float.NEGATIVE_INFINITY;
        float maxY = Float.NEGATIVE_INFINITY;
        float maxZ = Float.NEGATIVE_INFINITY;
        for (int i = 0; i < p.length; i += 3) {
            minX = Math.min(minX, p[i]);
            minY = Math.min(minY, p[i + 1]);
            minZ = Math.min(minZ, p[i + 2]);
            maxX = Math.max(maxX, p[i]);
            maxY = Math.max(maxY, p[i + 1]);
            maxZ = Math.max(maxZ, p[i + 2]);
        }

        return new Chunk(brickId, b.bx, b.by, b.bz, nextRevision++,
                p, n, ii, minX, minY, minZ, maxX, maxY, maxZ);
    }

    private void polygonizeTet(int[] tet,
                               int[] pointId,
                               int[] gx, int[] gy, int[] gz,
                               float[] value,
                               float[] gradient,
                               PrimitiveLongIntMap edgeVertex,
                               FloatList positions,
                               ShortList indices) {
        int[] inside = new int[4];
        int[] outside = new int[4];
        int insideCount = 0;
        int outsideCount = 0;

        for (int q = 0; q < 4; q++) {
            int c = tet[q];
            if (value[c] < 0f) inside[insideCount++] = c;
            else outside[outsideCount++] = c;
        }
        if (insideCount == 0 || insideCount == 4) return;

        tetraGradient(tet, gx, gy, gz, value, gradient);
        if (lengthSquared(gradient[0], gradient[1], gradient[2]) < GRADIENT_EPS) {
            // A sign-changing tetrahedron should have a usable linear gradient,
            // but fixed-point fields can get extremely flat. The inside->outside
            // centroid direction is a deterministic fallback with the same sign
            // meaning: positive SDF is outside.
            centroidDirection(inside, insideCount, outside, outsideCount,
                    gx, gy, gz, gradient);
        }

        if (insideCount == 1) {
            int a = inside[0];
            int v0 = edgeVertex(a, outside[0], pointId, gx, gy, gz, value, edgeVertex, positions);
            int v1 = edgeVertex(a, outside[1], pointId, gx, gy, gz, value, edgeVertex, positions);
            int v2 = edgeVertex(a, outside[2], pointId, gx, gy, gz, value, edgeVertex, positions);
            emitOutward(v0, v1, v2, gradient, positions, indices);
        } else if (insideCount == 3) {
            int o = outside[0];
            int v0 = edgeVertex(o, inside[0], pointId, gx, gy, gz, value, edgeVertex, positions);
            int v1 = edgeVertex(o, inside[1], pointId, gx, gy, gz, value, edgeVertex, positions);
            int v2 = edgeVertex(o, inside[2], pointId, gx, gy, gz, value, edgeVertex, positions);
            emitOutward(v0, v1, v2, gradient, positions, indices);
        } else {
            int a = inside[0];
            int b = inside[1];
            int c = outside[0];
            int d = outside[1];
            int p0 = edgeVertex(a, c, pointId, gx, gy, gz, value, edgeVertex, positions);
            int p1 = edgeVertex(a, d, pointId, gx, gy, gz, value, edgeVertex, positions);
            int p2 = edgeVertex(b, c, pointId, gx, gy, gz, value, edgeVertex, positions);
            int p3 = edgeVertex(b, d, pointId, gx, gy, gz, value, edgeVertex, positions);
            // Cyclic quad order is p0 -> p1 -> p3 -> p2. Both triangles are
            // then oriented from negative SDF (inside) toward positive SDF.
            emitOutward(p0, p1, p3, gradient, positions, indices);
            emitOutward(p0, p3, p2, gradient, positions, indices);
        }
    }

    /** Exact gradient of the tetrahedron's linear scalar interpolant. */
    private static void tetraGradient(int[] tet,
                                      int[] gx, int[] gy, int[] gz,
                                      float[] value,
                                      float[] out) {
        int a = tet[0], b = tet[1], c = tet[2], d = tet[3];
        float e1x = gx[b] - gx[a], e1y = gy[b] - gy[a], e1z = gz[b] - gz[a];
        float e2x = gx[c] - gx[a], e2y = gy[c] - gy[a], e2z = gz[c] - gz[a];
        float e3x = gx[d] - gx[a], e3y = gy[d] - gy[a], e3z = gz[d] - gz[a];
        float f1 = value[b] - value[a];
        float f2 = value[c] - value[a];
        float f3 = value[d] - value[a];

        float c23x = e2y * e3z - e2z * e3y;
        float c23y = e2z * e3x - e2x * e3z;
        float c23z = e2x * e3y - e2y * e3x;
        float c31x = e3y * e1z - e3z * e1y;
        float c31y = e3z * e1x - e3x * e1z;
        float c31z = e3x * e1y - e3y * e1x;
        float c12x = e1y * e2z - e1z * e2y;
        float c12y = e1z * e2x - e1x * e2z;
        float c12z = e1x * e2y - e1y * e2x;
        float det = e1x * c23x + e1y * c23y + e1z * c23z;

        if (Math.abs(det) < 1.0e-12f) {
            out[0] = out[1] = out[2] = 0f;
            return;
        }
        float inv = 1f / det;
        out[0] = (f1 * c23x + f2 * c31x + f3 * c12x) * inv;
        out[1] = (f1 * c23y + f2 * c31y + f3 * c12y) * inv;
        out[2] = (f1 * c23z + f2 * c31z + f3 * c12z) * inv;
    }

    private static void centroidDirection(int[] inside, int ni,
                                          int[] outside, int no,
                                          int[] gx, int[] gy, int[] gz,
                                          float[] out) {
        float ix = 0f, iy = 0f, iz = 0f;
        float ox = 0f, oy = 0f, oz = 0f;
        for (int i = 0; i < ni; i++) {
            int c = inside[i];
            ix += gx[c]; iy += gy[c]; iz += gz[c];
        }
        for (int i = 0; i < no; i++) {
            int c = outside[i];
            ox += gx[c]; oy += gy[c]; oz += gz[c];
        }
        ix /= ni; iy /= ni; iz /= ni;
        ox /= no; oy /= no; oz /= no;
        out[0] = ox - ix;
        out[1] = oy - iy;
        out[2] = oz - iz;
    }

    private int edgeVertex(int ca, int cb,
                           int[] pointId,
                           int[] gx, int[] gy, int[] gz,
                           float[] value,
                           PrimitiveLongIntMap map,
                           FloatList positions) {
        int pa = pointId[ca];
        int pb = pointId[cb];
        int lo = Math.min(pa, pb);
        int hi = Math.max(pa, pb);
        long key = ((long) lo << 32) | (hi & 0xffffffffL);
        int old = map.get(key, -1);
        if (old >= 0) return old;

        // Canonical endpoint ordering makes the interpolation operation itself
        // identical on both sides of a chunk boundary, not merely numerically
        // close after welding.
        int a = ca;
        int b = cb;
        if (compareLattice(gx[ca], gy[ca], gz[ca], gx[cb], gy[cb], gz[cb]) > 0) {
            a = cb;
            b = ca;
        }

        float va = value[a];
        float vb = value[b];
        float denominator = va - vb;
        float t = Math.abs(denominator) < 1e-20f ? 0.5f : va / denominator;
        t = Math.max(0f, Math.min(1f, t));

        float x = (gx[a] + (gx[b] - gx[a]) * t) * AvsVolume.VOXEL_SIZE;
        float y = (gy[a] + (gy[b] - gy[a]) * t) * AvsVolume.VOXEL_SIZE;
        float z = (gz[a] + (gz[b] - gz[a]) * t) * AvsVolume.VOXEL_SIZE;

        int id = positions.size / 3;
        if (id >= 65535) {
            throw new IllegalStateException("AVS chunk exceeds 16-bit vertex range");
        }
        positions.add(x);
        positions.add(y);
        positions.add(z);
        map.put(key, id, -1);
        return id;
    }

    private static int compareLattice(int ax, int ay, int az, int bx, int by, int bz) {
        if (ax != bx) return Integer.compare(ax, bx);
        if (ay != by) return Integer.compare(ay, by);
        return Integer.compare(az, bz);
    }

    private static void emitOutward(int a, int b, int c,
                                    float[] gradient,
                                    FloatList positions,
                                    ShortList indices) {
        if (a == b || b == c || c == a) return;
        int ia = a * 3, ib = b * 3, ic = c * 3;
        float abx = positions.data[ib] - positions.data[ia];
        float aby = positions.data[ib + 1] - positions.data[ia + 1];
        float abz = positions.data[ib + 2] - positions.data[ia + 2];
        float acx = positions.data[ic] - positions.data[ia];
        float acy = positions.data[ic + 1] - positions.data[ia + 1];
        float acz = positions.data[ic + 2] - positions.data[ia + 2];
        float fx = aby * acz - abz * acy;
        float fy = abz * acx - abx * acz;
        float fz = abx * acy - aby * acx;
        float area2 = (float) Math.sqrt(fx * fx + fy * fy + fz * fz);
        if (!(area2 > FACE_AREA_EPS) || !Float.isFinite(area2)) return;

        // SDF convention is negative-inside / positive-outside. The exact
        // tetrahedral scalar gradient therefore *is* the outward direction.
        if (fx * gradient[0] + fy * gradient[1] + fz * gradient[2] < 0f) {
            int tmp = b;
            b = c;
            c = tmp;
        }
        indices.add((short) a);
        indices.add((short) b);
        indices.add((short) c);
    }

    private float[] buildNormals(float[] p, short[] indices) {
        float[] geometric = new float[p.length];
        for (int i = 0; i < indices.length; i += 3) {
            int a = (indices[i] & 0xffff) * 3;
            int b = (indices[i + 1] & 0xffff) * 3;
            int c = (indices[i + 2] & 0xffff) * 3;
            float abx = p[b] - p[a], aby = p[b + 1] - p[a + 1], abz = p[b + 2] - p[a + 2];
            float acx = p[c] - p[a], acy = p[c + 1] - p[a + 1], acz = p[c + 2] - p[a + 2];
            float nx = aby * acz - abz * acy;
            float ny = abz * acx - abx * acz;
            float nz = abx * acy - aby * acx;
            geometric[a] += nx; geometric[a + 1] += ny; geometric[a + 2] += nz;
            geometric[b] += nx; geometric[b + 1] += ny; geometric[b + 2] += nz;
            geometric[c] += nx; geometric[c + 1] += ny; geometric[c + 2] += nz;
        }

        float[] normals = new float[p.length];
        for (int i = 0; i < p.length; i += 3) {
            float gx = geometric[i], gy = geometric[i + 1], gz = geometric[i + 2];
            float gl = (float) Math.sqrt(gx * gx + gy * gy + gz * gz);
            if (gl > 1e-12f) {
                gx /= gl; gy /= gl; gz /= gl;
            } else {
                gx = 0f; gy = 0f; gz = 1f;
            }

            volume.gradient(p[i], p[i + 1], p[i + 2], gradientScratch);
            float sx = gradientScratch[0], sy = gradientScratch[1], sz = gradientScratch[2];
            float dot = sx * gx + sy * gy + sz * gz;

            // Cross-chunk shading uses the SDF gradient when it agrees with the
            // oriented surface. Near CSG creases the sampled gradient can be
            // unstable, so geometric orientation is the safe fallback.
            if (Float.isFinite(dot) && dot > 0.20f) {
                float nx = sx + gx * 0.35f;
                float ny = sy + gy * 0.35f;
                float nz = sz + gz * 0.35f;
                float nl = (float) Math.sqrt(nx * nx + ny * ny + nz * nz);
                if (nl > 1e-12f) {
                    normals[i] = nx / nl;
                    normals[i + 1] = ny / nl;
                    normals[i + 2] = nz / nl;
                    continue;
                }
            }
            normals[i] = gx;
            normals[i + 1] = gy;
            normals[i + 2] = gz;
        }
        return normals;
    }

    private void ensureChunkCapacity(int needed) {
        if (chunkByBrick.length >= needed) return;
        int cap = chunkByBrick.length;
        while (cap < needed) cap = cap + cap / 2 + 64;
        chunkByBrick = Arrays.copyOf(chunkByBrick, cap);
    }

    private static float lengthSquared(float x, float y, float z) {
        return x * x + y * y + z * z;
    }

    private static final class FloatList {
        float[] data;
        int size;
        FloatList(int capacity) { data = new float[Math.max(16, capacity)]; }
        void add(float v) {
            if (size == data.length) data = Arrays.copyOf(data, data.length + data.length / 2 + 64);
            data[size++] = v;
        }
    }

    private static final class ShortList {
        short[] data;
        int size;
        ShortList(int capacity) { data = new short[Math.max(16, capacity)]; }
        void add(short v) {
            if (size == data.length) data = Arrays.copyOf(data, data.length + data.length / 2 + 64);
            data[size++] = v;
        }
    }
}

package com.fallpoint.pocketsculpt;

/**
 * Thin runtime facade for CABrush AVS 0.1.
 *
 * The signed-distance volume is sculpt truth. AvsSurfaceCache is disposable
 * rendering cache and can be rebuilt at any time.
 */
final class SculptMesh {
    static final class Hit {
        float x,y,z,nx,ny,nz,t;
        Hit set(AvsVolume.RayHit h) {
            x=h.x; y=h.y; z=h.z; nx=h.nx; ny=h.ny; nz=h.nz; t=h.t;
            return this;
        }
    }

    final AvsVolume volume;
    final AvsSurfaceCache surface;
    private final AvsSnapshot resetSnapshot;
    private final AvsVolume.RayHit rayScratch = new AvsVolume.RayHit();
    private final Hit hitScratch = new Hit();

    private SculptMesh(AvsVolume volume) {
        this.volume = volume;
        this.surface = new AvsSurfaceCache(volume);
        this.resetSnapshot = volume.snapshot();
        this.surface.rebuildAll();
    }

    static SculptMesh createSphere() {
        return new SculptMesh(AvsVolume.createSphere(1f));
    }

    Hit raycast(float[] origin, float[] direction) {
        if (origin == null || direction == null || origin.length < 3 || direction.length < 3) return null;
        AvsVolume.RayHit h = volume.raycast(
                origin[0],origin[1],origin[2],
                direction[0],direction[1],direction[2],
                rayScratch
        );
        return h.hit ? hitScratch.set(h) : null;
    }

    AvsVolume.BrushResult applyClay(float hitX,float hitY,float hitZ,
                                     float normalX,float normalY,float normalZ,
                                     float radius,float strength,BrushMode mode) {
        return volume.applyClay(
                hitX,hitY,hitZ,normalX,normalY,normalZ,radius,strength,mode
        );
    }

    void reset() {
        long start = EngineDiagnostics.nowNanos();
        resetSnapshot.restoreInto(volume);
        surface.rebuildAll();
        if (EngineDiagnostics.isEnabled()) {
            EngineDiagnostics.timed("mesh", "reset", start,
                    "bricks=" + volume.brickCount()
                            + " field_hash=" + volume.fieldHash());
        }
    }

    AvsSurfaceCache.RenderPlan renderPlan() {
        return surface.currentPlan();
    }

    AvsVolume.Stats stats() { return volume.stats(); }

    String fieldHash() { return volume.fieldHash(); }
}

package com.fallpoint.pocketsculpt;

import android.opengl.GLES30;
import android.opengl.GLSurfaceView;
import android.opengl.Matrix;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.FloatBuffer;
import java.nio.ShortBuffer;
import java.util.Arrays;

import javax.microedition.khronos.egl.EGLConfig;
import javax.microedition.khronos.opengles.GL10;

/** Android GL shell for CABrush AVS. CPU sculpt truth lives only in AvsVolume. */
public final class SculptRenderer implements GLSurfaceView.Renderer {
    private final float[] projection = new float[16];
    private final float[] view = new float[16];
    private final float[] model = new float[16];
    private final float[] vp = new float[16];
    private final float[] mvp = new float[16];
    private final float[] inverseMvp = new float[16];
    private final float[] unprojectIn = new float[4];
    private final float[] unprojectOut = new float[4];
    private final float[] rayNear = new float[3];
    private final float[] rayFar = new float[3];
    private final Ray rayScratch = new Ray();

    private SculptMesh mesh;
    private GpuChunk[] gpuByBrick = new GpuChunk[256];

    private int program;
    private int aPosition;
    private int aNormal;
    private int uMvp;
    private int uLightDirection;

    private int width = 1;
    private int height = 1;

    private BrushMode brushMode = BrushMode.ADD;
    private float brushRadius = 0.30f;
    private float brushStrength = 0.020f;

    private float yaw = 22f;
    private float pitch = 8f;
    private float cameraDistance = 4.0f;

    private boolean strokeActive;
    private boolean hasLastDab;
    private float lastDabX, lastDabY;

    // Deep diagnostics state. It is inert when EngineDiagnostics is disabled.
    private long frameNumber;
    private long lastFrameStartNanos;
    private long frameBatchRenderNanos;
    private long frameBatchIntervalNanos;
    private long frameBatchMaxRenderNanos;
    private long frameBatchMaxIntervalNanos;
    private int frameBatchCount;

    private long strokeId;
    private long strokeStartNanos;
    private int strokeDabCount;
    private int strokeChangedDabs;
    private int strokeRayMisses;
    private boolean strokeHasFirstHit;
    private float firstHitX, firstHitY, firstHitZ;
    private float firstHitNx, firstHitNy, firstHitNz;
    private float previousHitX, previousHitY, previousHitZ, previousHitT;
    private float previousHitScreenX, previousHitScreenY;
    private boolean hasPreviousHit;
    private float strokeMaxNormalExcursion;

    @Override
    public void onSurfaceCreated(GL10 gl, EGLConfig config) {
        long start = EngineDiagnostics.nowNanos();
        GLES30.glClearColor(0.075f, 0.086f, 0.102f, 1f);
        GLES30.glEnable(GLES30.GL_DEPTH_TEST);
        GLES30.glEnable(GLES30.GL_CULL_FACE);
        // AVS Surface Truth contract: extractor emits outward CCW faces.
        GLES30.glFrontFace(GLES30.GL_CCW);
        GLES30.glCullFace(GLES30.GL_BACK);

        program = buildProgram(VERTEX_SHADER, FRAGMENT_SHADER);
        aPosition = GLES30.glGetAttribLocation(program, "aPosition");
        aNormal = GLES30.glGetAttribLocation(program, "aNormal");
        uMvp = GLES30.glGetUniformLocation(program, "uMvp");
        uLightDirection = GLES30.glGetUniformLocation(program, "uLightDirection");

        if (mesh == null) mesh = SculptMesh.createSphere();
        Matrix.setIdentityM(model, 0);
        gpuByBrick = new GpuChunk[Math.max(256, mesh.volume.brickCount() + 64)];

        if (EngineDiagnostics.isEnabled()) {
            String vendor = String.valueOf(GLES30.glGetString(GLES30.GL_VENDOR));
            String renderer = String.valueOf(GLES30.glGetString(GLES30.GL_RENDERER));
            String version = String.valueOf(GLES30.glGetString(GLES30.GL_VERSION));
            String shading = String.valueOf(GLES30.glGetString(GLES30.GL_SHADING_LANGUAGE_VERSION));
            EngineDiagnostics.state("gl.vendor", vendor);
            EngineDiagnostics.state("gl.renderer", renderer);
            EngineDiagnostics.state("gl.version", version);
            EngineDiagnostics.state("gl.shading_language", shading);
            EngineDiagnostics.state("gl.extensions",
                    String.valueOf(GLES30.glGetString(GLES30.GL_EXTENSIONS)));
            int[] glValue = new int[1];
            GLES30.glGetIntegerv(GLES30.GL_MAX_TEXTURE_SIZE, glValue, 0);
            EngineDiagnostics.state("gl.max_texture_size", String.valueOf(glValue[0]));
            GLES30.glGetIntegerv(GLES30.GL_MAX_VERTEX_ATTRIBS, glValue, 0);
            EngineDiagnostics.state("gl.max_vertex_attribs", String.valueOf(glValue[0]));
            GLES30.glGetIntegerv(GLES30.GL_MAX_VERTEX_UNIFORM_VECTORS, glValue, 0);
            EngineDiagnostics.state("gl.max_vertex_uniform_vectors", String.valueOf(glValue[0]));
            GLES30.glGetIntegerv(GLES30.GL_MAX_FRAGMENT_UNIFORM_VECTORS, glValue, 0);
            EngineDiagnostics.state("gl.max_fragment_uniform_vectors", String.valueOf(glValue[0]));
            EngineDiagnostics.state("renderer.front_face", "CCW");
            EngineDiagnostics.state("renderer.cull_face", "BACK");
            EngineDiagnostics.record("renderer", "surface_created",
                    "vendor=" + vendor + " renderer=" + renderer
                            + " version=" + version + " glsl=" + shading);
            EngineDiagnostics.timed("renderer", "surface_create", start,
                    "bricks=" + mesh.volume.brickCount());
            checkGlErrors("surface_created");
        }
    }

    @Override
    public void onSurfaceChanged(GL10 gl, int width, int height) {
        this.width = Math.max(1, width);
        this.height = Math.max(1, height);
        GLES30.glViewport(0, 0, this.width, this.height);
        Matrix.perspectiveM(projection, 0, 42f, (float)this.width / this.height, 0.1f, 100f);
        if (EngineDiagnostics.isEnabled()) {
            EngineDiagnostics.state("renderer.viewport", this.width + "x" + this.height);
            EngineDiagnostics.record("renderer", "surface_changed",
                    "width=" + this.width + " height=" + this.height
                            + " aspect=" + ((float)this.width / this.height));
            checkGlErrors("surface_changed");
        }
    }

    @Override
    public void onDrawFrame(GL10 gl) {
        if (mesh == null) return;
        long frameStart = EngineDiagnostics.nowNanos();
        long intervalNs = 0L;
        if (EngineDiagnostics.isEnabled() && lastFrameStartNanos != 0L) {
            intervalNs = frameStart - lastFrameStartNanos;
        }
        if (EngineDiagnostics.isEnabled()) lastFrameStartNanos = frameStart;

        GLES30.glClear(GLES30.GL_COLOR_BUFFER_BIT | GLES30.GL_DEPTH_BUFFER_BIT);
        updateMatrices();

        AvsSurfaceCache.RenderPlan plan = mesh.renderPlan();
        syncGpuChunks(plan);

        GLES30.glUseProgram(program);
        GLES30.glUniformMatrix4fv(uMvp, 1, false, mvp, 0);
        GLES30.glUniform3f(uLightDirection, -0.35f, 0.72f, 0.58f);
        GLES30.glEnableVertexAttribArray(aPosition);
        GLES30.glEnableVertexAttribArray(aNormal);

        int drawCalls = 0;
        int indicesDrawn = 0;
        for (AvsSurfaceCache.Chunk source : plan.chunks) {
            GpuChunk chunk = gpuByBrick[source.brickId];
            if (chunk == null || chunk.indexCount == 0) continue;
            chunk.positionBuffer.position(0);
            chunk.normalBuffer.position(0);
            chunk.indexBuffer.position(0);
            GLES30.glVertexAttribPointer(aPosition, 3, GLES30.GL_FLOAT, false, 0, chunk.positionBuffer);
            GLES30.glVertexAttribPointer(aNormal, 3, GLES30.GL_FLOAT, false, 0, chunk.normalBuffer);
            GLES30.glDrawElements(GLES30.GL_TRIANGLES, chunk.indexCount, GLES30.GL_UNSIGNED_SHORT, chunk.indexBuffer);
            drawCalls++;
            indicesDrawn += chunk.indexCount;
        }

        GLES30.glDisableVertexAttribArray(aPosition);
        GLES30.glDisableVertexAttribArray(aNormal);

        if (EngineDiagnostics.isEnabled()) {
            long renderNs = System.nanoTime() - frameStart;
            frameNumber++;
            frameBatchCount++;
            frameBatchRenderNanos += renderNs;
            frameBatchIntervalNanos += intervalNs;
            frameBatchMaxRenderNanos = Math.max(frameBatchMaxRenderNanos, renderNs);
            frameBatchMaxIntervalNanos = Math.max(frameBatchMaxIntervalNanos, intervalNs);

            EngineDiagnostics.counter("renderer.frames", 1L);
            EngineDiagnostics.counter("renderer.draw_calls", drawCalls);
            EngineDiagnostics.counter("renderer.indices_drawn", indicesDrawn);
            EngineDiagnostics.gauge("renderer.last_frame_render_ms", renderNs / 1_000_000.0);
            if (intervalNs > 0L) {
                EngineDiagnostics.gauge("renderer.last_frame_interval_ms", intervalNs / 1_000_000.0);
            }

            if (frameBatchCount >= 30) {
                double avgRenderMs = frameBatchRenderNanos / (double) frameBatchCount / 1_000_000.0;
                double avgIntervalMs = frameBatchIntervalNanos / (double) frameBatchCount / 1_000_000.0;
                EngineDiagnostics.gauge("renderer.avg_render_ms_30", avgRenderMs);
                EngineDiagnostics.gauge("renderer.avg_interval_ms_30", avgIntervalMs);
                EngineDiagnostics.gauge("renderer.max_render_ms_30",
                        frameBatchMaxRenderNanos / 1_000_000.0);
                EngineDiagnostics.gauge("renderer.max_interval_ms_30",
                        frameBatchMaxIntervalNanos / 1_000_000.0);
                EngineDiagnostics.record("renderer", "frame_batch",
                        "frame=" + frameNumber
                                + " count=" + frameBatchCount
                                + " avg_render_ms=" + avgRenderMs
                                + " max_render_ms=" + (frameBatchMaxRenderNanos / 1_000_000.0)
                                + " avg_interval_ms=" + avgIntervalMs
                                + " max_interval_ms=" + (frameBatchMaxIntervalNanos / 1_000_000.0)
                                + " draw_calls=" + drawCalls
                                + " chunks=" + plan.chunks.length
                                + " triangles=" + plan.totalTriangles);
                frameBatchCount = 0;
                frameBatchRenderNanos = 0L;
                frameBatchIntervalNanos = 0L;
                frameBatchMaxRenderNanos = 0L;
                frameBatchMaxIntervalNanos = 0L;
                checkGlErrors("frame_batch");
            }

            if (frameNumber > 5 && intervalNs > 250_000_000L) {
                EngineDiagnostics.anomaly("frame_stall",
                        "frame=" + frameNumber
                                + " interval_ns=" + intervalNs
                                + " render_ns=" + renderNs
                                + " dirty=" + plan.dirtyBefore
                                + " rebuilt=" + plan.rebuiltChunks
                                + " triangles=" + plan.totalTriangles);
            }

            if ((frameNumber % 120L) == 0L) {
                Runtime rt = Runtime.getRuntime();
                EngineDiagnostics.gauge("memory.java_used_mb",
                        (rt.totalMemory() - rt.freeMemory()) / 1048576.0);
                EngineDiagnostics.gauge("memory.java_total_mb",
                        rt.totalMemory() / 1048576.0);
            }
        }
    }

